    en: { howTo:{title:"How to use Merge PDF",steps:["Select or drag PDFs.","Use arrows to order and Remove to take out files.","Select Merge PDFs and download the result."]}, example:{title:"Example with three documents",description:"Add cover.pdf, report.pdf, and attachments.pdf in that order.",calculation:"cover.pdf + report.pdf + attachments.pdf -> merged.pdf",result:"Pages are copied in list order into one PDF."}, useCases:{title:"Use cases",items:["Gather a cover and attachments.","Order separately received PDFs.","Prepare one attachment."]}, notes:{title:"Notes and limitations",items:["It accepts multiple PDFs, lets you reorder with arrows, and remove items.","Each file can be 25 MB and total 100 MB; there is no separate count limit.","It uses pdf-lib to load each file and copy pages in current order into a new PDF.","Invalid, corrupted, protected, or unsupported PDFs can cause an error. It does not perform OCR, editing, or automatic compression; special features can change."]}, faq:{title:"Frequently asked questions",items:[{question:"Can I change order?",answer:"Yes. Use the list arrows."},{question:"What is the limit?",answer:"25 MB per PDF and 100 MB total."},{question:"Does it edit text?",answer:"No. It copies pages and offers no OCR or editing."}]}, relatedTools:{title:"Related tools",items:[{toolId:"jpg-para-pdf",label:"JPG to PDF",description:"Create an image PDF before combining it."},{toolId:"comprimir-pdf",label:"Compress PDF",description:"Rebuild one PDF and check its size."}]} },
    es: { howTo:{title:"Como usar Combinar PDF",steps:["Selecciona o arrastra los PDF.","Usa flechas para ordenar y Eliminar para quitar archivos.","Selecciona Combinar PDF y descarga el resultado."]}, example:{title:"Ejemplo con tres documentos",description:"Agrega portada.pdf, informe.pdf y anexos.pdf en ese orden.",calculation:"portada.pdf + informe.pdf + anexos.pdf -> merged.pdf",result:"Las paginas se copian en orden de lista a un PDF."}, useCases:{title:"Casos de uso",items:["Reunir portada y anexos.","Ordenar PDF recibidos por separado.","Preparar un unico adjunto."]}, notes:{title:"Notas y limitaciones",items:["Acepta varios PDF, permite reordenar con flechas y eliminar elementos.","Cada archivo puede tener 25 MB y el total 100 MB; no hay limite separado de cantidad.","Usa pdf-lib para cargar cada archivo y copiar paginas en orden actual a un PDF nuevo.","PDF invalidos, danados, protegidos o no compatibles pueden causar error. No realiza OCR, edicion ni compresion automatica; funciones especiales pueden cambiar."]}, faq:{title:"Preguntas frecuentes",items:[{question:"Puedo cambiar el orden?",answer:"Si. Usa las flechas de la lista."},{question:"Cual es el limite?",answer:"25 MB por PDF y 100 MB total."},{question:"Edita el texto?",answer:"No. Copia paginas y no ofrece OCR ni edicion."}]}, relatedTools:{title:"Herramientas relacionadas",items:[{toolId:"jpg-para-pdf",label:"JPG a PDF",description:"Crea un PDF de imagen antes de combinarlo."},{toolId:"comprimir-pdf",label:"Comprimir PDF",description:"Reconstruye un PDF y revisa su tamano."}]} },
